#:sdk Microsoft.NET.Sdk.Web
#:property PublishAot=false

// (That second line just silences native-AOT trimming warnings that
// file-based web apps emit for reflection-based JSON — ignore it.)
//
// 35 — integration testing (ORIGINAL, flawed on purpose)
//
// A small orders API with ZERO tests. Not "a few tests". Zero. It was written
// in an afternoon, it demoed fine, and it has been in production for a year.
//
// It also has a BUG CHAIN — three faults that each look survivable alone and
// combine into "the invoice totals are wrong and the app says everything is
// fine". Every one of them is invisible to the unit tests nobody wrote, and
// two of them are invisible to unit tests even if you DO write them, because
// they live in the space between the code and HTTP.
//
// Run:   dotnet run csharp/35-integration-testing/original.cs
// Try:
//   curl -X POST http://localhost:5035/orders -H "Content-Type: application/json" \
//        -d "{\"lines\":[{\"sku\":\"BOOK-1\",\"qty\":3,\"unitPrice\":19.99}]}"
//
//   BUG #1 — the money is wrong, and it is wrong in an ugly way:
//        subtotal 59.97, tax 4.7976, total 64.7676
//        Nobody's invoice says 64.7676. Round it for display and you get
//        59.97 + 4.80 = 64.77, but the server said 64.77 too... sometimes.
//        Watch what happens with qty 1 at 24.995 — doubles and Math.Round's
//        banker's rounding disagree with every accountant alive.
//
//   BUG #2 — a missing order is a SUCCESS:
//   curl -i http://localhost:5035/orders/999
//        -> HTTP/1.1 200 OK
//        -> null
//        The client asked for an order that does not exist and was told
//        "here you go". Every `if (res.ok)` on the planet takes the happy path
//        and then explodes on `order.total` — in the CLIENT, three files away
//        from the actual mistake.
//
//   BUG #3 — creating something returns 200, not 201, and no Location:
//   curl -i -X POST http://localhost:5035/orders -H "Content-Type: application/json" \
//        -d "{\"lines\":[{\"sku\":\"MUG-1\",\"qty\":1,\"unitPrice\":9.5}]}"
//        -> HTTP/1.1 200 OK, and no Location header telling you where it went.
//
// Read the three bugs again and ask project 01's question: HOW WOULD I TEST
// THIS? Bug #1 needs a test of the arithmetic. Bugs #2 and #3 are about status
// codes and headers — there is no function you could call to check them,
// because the mistake IS the HTTP translation. That gap is what project 35 is
// about.

var app = WebApplication.CreateBuilder(args).Build();

var orders = new List<Order>();
var nextId = 1;

app.MapPost("/orders", (NewOrder dto) =>
{
    if (dto.Lines is null || dto.Lines.Count == 0)
        return Results.BadRequest("an order needs at least one line");

    // BUG #1, part one: money in `double`. Doubles are binary fractions, and
    // 0.1 is no more representable in binary than 1/3 is in decimal — so
    // 19.99 is actually 19.989999999999998436805981327. Multiply, add, and
    // the error compounds. This is why every currency value in every serious
    // system is a decimal (or an integer number of cents), never a double.
    double subtotal = 0;
    foreach (var line in dto.Lines)
        subtotal += line.Qty * line.UnitPrice;

    double tax = subtotal * 0.08;

    // BUG #1, part two: the pieces and the whole are rounded INCONSISTENTLY.
    // The total is rounded; subtotal and tax are not. So the response can say
    // 59.97 + 4.7976 = 64.77, which is three numbers that do not add up, and
    // whichever one the client trusts, some other screen disagrees.
    //
    // BUG #1, part three: Math.Round uses BANKER'S ROUNDING by default —
    // 2.675 rounds to 2.68 but 2.665 rounds to 2.66, because it rounds ties
    // to the nearest EVEN digit. It is a defensible statistical choice and it
    // is not what invoices do. Nobody wrote MidpointRounding.AwayFromZero
    // because nobody knew there was a choice.
    double total = Math.Round(subtotal + tax, 2);

    var order = new Order(nextId++, dto.Lines, subtotal, tax, total);
    orders.Add(order);

    // BUG #3: 200 OK for something that CREATED a resource, and no Location
    // header. REST says 201 Created + Location (cs#16). A client that wants
    // the new order's URL has to build it from the id and hope.
    return Results.Ok(order);
});

app.MapGet("/orders/{id}", (int id) =>
{
    var order = orders.FirstOrDefault(o => o.Id == id);

    // BUG #2: `order` is null when nothing matched, and Results.Ok(null)
    // is a perfectly cheerful 200 with the body `null`. The one line that
    // would fix it — `if (order is null) return Results.NotFound();` — was
    // never written, and no test could have missed it, because there are no
    // tests.
    return Results.Ok(order);
});

app.MapGet("/orders", () => Results.Ok(orders));

app.Run("http://localhost:5035");

record OrderLine(string Sku, int Qty, double UnitPrice);
record NewOrder(List<OrderLine>? Lines);
record Order(int Id, List<OrderLine> Lines, double Subtotal, double Tax, double Total);

# 🏋️ Practice: Integration Testing

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Your first endpoint tested over HTTP (warm-up)

Add `GET /health` returning `200` with `{ "status": "ok", "orders": <count> }`, give `OrderStore` a
`Count` property, and assert all of it from `HttpTests.Suite`. The endpoint is three lines; the point is
to walk the harness loop once with something you cannot get wrong.
*Practices:* the shape of an HTTP assertion — status code, then parsed body.
**Hint:** declare a `private record HealthDto(string Status, int Orders);` next to the others in
`HttpTests`. `ReadFromJsonAsync` matches `status`/`orders` to `Status`/`Orders` case-insensitively, so
you never write a naming policy.
**Check offline:** add to `HttpTests.Suite`, at the very top (before anything is created):
```csharp
var health = await http.GetAsync("/health");
Check.Equal(200, (int)health.StatusCode, "[http] GET /health is 200");
var h = await health.Content.ReadFromJsonAsync<HealthDto>();
Check.Equal("ok", h!.Status, "[http] ...and says ok");
Check.Equal(0, h.Orders, "[http] ...with a zero order count on a fresh server");
```
and after the first successful POST:
```csharp
Check.Equal(1, (await (await http.GetAsync("/health")).Content.ReadFromJsonAsync<HealthDto>())!.Orders,
    "[http] the health count tracks reality");
```

### ⭐⭐ 2. PUT, and three status codes that only HTTP can check (core)

Add `PUT /orders/{id:int}` that replaces an order's lines and recomputes its totals: `200` with the
updated order, `404` if the id doesn't exist, `400` if the body is invalid. Add `OrderStore.Replace`.
Then decide — and defend in a test — what `PUT /orders/999` with an *empty* body should return: 400 or
404?
*Practices:* an endpoint whose entire risk surface is status codes, and ordering your guards on purpose.
**Hint:** `Replace` is `FindIndex` + a new `Order` with the same id, all inside the lock — the same
read-modify-write shape as cs#21. In the endpoint, validate the body **first**: an unparseable request
cannot be acted on whatever the id is, and answering 404 would tell a stranger which ids exist before
you have even accepted their request.
**Check offline:** add to `HttpTests.Suite`:
```csharp
var put = await http.PutAsJsonAsync("/orders/1", new { lines = new[] { new { sku = "B", qty = 4, unitPrice = 25m } } });
Check.Equal(200, (int)put.StatusCode, "[http] PUT on an existing order is 200");
var updated = await put.Content.ReadFromJsonAsync<OrderDto>();
Check.Equal(1, updated!.Id, "[http] ...keeping its id");
Check.Equal(100.00m, updated.Subtotal, "[http] ...and recomputing the totals");
Check.Equal(108.00m, updated.Total, "[http] ...including tax");
Check.Equal(108.00m, (await (await http.GetAsync("/orders/1")).Content.ReadFromJsonAsync<OrderDto>())!.Total,
    "[http] and the change was actually stored");

Check.Equal(404, (int)(await http.PutAsJsonAsync("/orders/999",
    new { lines = new[] { new { sku = "B", qty = 1, unitPrice = 1m } } })).StatusCode,
    "[http] PUT on a missing order is 404");
Check.Equal(400, (int)(await http.PutAsJsonAsync("/orders/1", new { lines = Array.Empty<object>() })).StatusCode,
    "[http] PUT with no lines is 400");
Check.Equal(400, (int)(await http.PutAsJsonAsync("/orders/999", new { lines = Array.Empty<object>() })).StatusCode,
    "[http] a bad body beats a missing id: 400, not 404");
```
Place these *before* the delete section, while order 1 still exists.

### ⭐⭐ 3. A discount, and the invariant that must survive it (core)

Orders of 100.00 or more get 10% off, and tax is charged on the **discounted** amount. Add `Discount`
to the tuple `Totals.For` returns and to the `Order` record. The interesting part is that the invariant
changes shape: it is no longer `Subtotal + Tax == Total` but `Subtotal - Discount + Tax == Total` — and
it must still hold exactly, for every input. Extend the property test to prove it.
*Practices:* growing pure arithmetic without breaking a guarantee, and boundary values.
**Hint:** round the discount, then compute tax on `subtotal - discount` and round that, then add three
already-rounded numbers. The threshold is *inclusive* — test 100.00 itself, and 99.99, because "greater
than" versus "greater than or equal" is the classic one-character bug.
**Check offline:** add to `Tests.cs`:
```csharp
var big = Totals.For([new OrderLine("A", 5, 25.00m)]);
Check.Equal(125.00m, big.Subtotal, "5 x 25.00 = 125.00");
Check.Equal(12.50m, big.Discount, "10% off over the threshold");
Check.Equal(9.00m, big.Tax, "tax is charged on the DISCOUNTED amount, not the subtotal");
Check.Equal(121.50m, big.Total, "125.00 - 12.50 + 9.00");

var exact = Totals.For([new OrderLine("A", 4, 25.00m)]);
Check.Equal(10.00m, exact.Discount, "the threshold is INCLUSIVE: exactly 100 qualifies");
Check.Equal(97.20m, exact.Total, "100 - 10 + 7.20");

var under = Totals.For([new OrderLine("A", 1, 99.99m)]);
Check.Equal(0m, under.Discount, "one cent under the threshold: no discount");
Check.Equal(107.99m, under.Total, "99.99 + 8.00");
```
and rewrite the property loop's condition to `subtotal - discount + tax != total`, also asserting
`Money.Round(discount) == discount`.

### ⭐⭐ 4. One server per scenario (core)

Right now `HttpTests.Suite` is one long story: order 1 must be created before it can be fetched, and
the "ids are not recycled" assertion depends on the delete that happened forty lines earlier. That is
fragile — reorder two blocks and things fail for reasons unrelated to the code. Extract a
`WithServer(Func<HttpClient, Task> scenario)` helper that starts a fresh app, runs one scenario, and
stops it, then split the suite into independent scenarios.
*Practices:* test independence, and paying an honest price for it.
**Hint:** the helper is the existing `RunAsync` body with the suite call replaced by `scenario(http)`.
Each call gets a brand-new `OrderStore` (it is registered per-app), so every scenario starts from an
empty world and every "the new order has id 1" assertion becomes true again.
**Check offline:** convert two scenarios and prove the isolation directly:
```csharp
await WithServer(async http =>
{
    var res = await http.PostAsJsonAsync("/orders", new { lines = new[] { new { sku = "A", qty = 1, unitPrice = 5m } } });
    Check.Equal(1, (await res.Content.ReadFromJsonAsync<OrderDto>())!.Id, "[http] scenario A: the first order is id 1");
});
await WithServer(async http =>
{
    var res = await http.PostAsJsonAsync("/orders", new { lines = new[] { new { sku = "B", qty = 1, unitPrice = 5m } } });
    Check.Equal(1, (await res.Content.ReadFromJsonAsync<OrderDto>())!.Id,
        "[http] scenario B: id 1 AGAIN — nothing leaked between scenarios");
});
```
Time the suite before and after. Fresh servers cost roughly a tenth of a second each; decide out loud
whether that is worth it here.

### ⭐⭐⭐ 5. Swap a service, the way `WebApplicationFactory` does (challenge)

The real testing package's headline feature is being able to run the whole HTTP stack with one service
replaced by a fake. Build that: give `Api.Build` an optional `Action<IServiceCollection>? configureServices`
applied **after** the app's own registrations, so a test's registration wins. Then use it twice — once
to start the server with a **pre-seeded** `OrderStore`, and once with a `FailingOrderStore` whose `All()`
throws, proving the API answers `500` when the store breaks.
*Practices:* the seam that makes integration tests fast and complete instead of only end-to-end.
**Hint:** the last `AddSingleton` for a type wins when you resolve one instance, so `configureServices`
just needs to run last. `FailingOrderStore : OrderStore` requires the methods you override to be
`virtual` — a small edit with a big payoff. Note that the failure test asserts something you cannot
provoke any other way: there is no valid request that makes a healthy store throw.
**Check offline:** add to `Tests.cs` / `HttpTests.cs`:
```csharp
var seeded = new OrderStore();
seeded.Add([new OrderLine("SEED-1", 1, 10m)]);
seeded.Add([new OrderLine("SEED-2", 2, 5m)]);
await WithServer(async http =>
{
    var list = await (await http.GetAsync("/orders")).Content.ReadFromJsonAsync<List<OrderDto>>();
    Check.Equal(2, list!.Count, "[http] the server started with a PRE-SEEDED store");
    Check.Equal(200, (int)(await http.GetAsync("/orders/1")).StatusCode, "[http] ...and the seeded orders are there");
    var next = await http.PostAsJsonAsync("/orders", new { lines = new[] { new { sku = "C", qty = 1, unitPrice = 1m } } });
    Check.Equal(3, (await next.Content.ReadFromJsonAsync<OrderDto>())!.Id, "[http] new orders continue the seeded ids");
}, services => services.AddSingleton(seeded));

await WithServer(async http =>
{
    Check.Equal(500, (int)(await http.GetAsync("/orders")).StatusCode,
        "[http] an injected failing store turns GET /orders into a 500");
    Check.Equal(200, (int)(await http.GetAsync("/health")).StatusCode,
        "[http] ...while unrelated endpoints still work");
}, services => services.AddSingleton<OrderStore>(new FailingOrderStore()));
```

## Solutions

### 1. Your first endpoint tested over HTTP

```csharp
// OrderStore.cs
public int Count { get { lock (_lock) return _orders.Count; } }

// Api.cs — in MapEndpoints
app.MapGet("/health", (OrderStore store) => Results.Ok(new { status = "ok", orders = store.Count }));

// HttpTests.cs — next to the other DTOs
private record HealthDto(string Status, int Orders);
```

WHY: a health endpoint is the smallest thing that is nonetheless *only* checkable over HTTP —
`store.Count` is trivially unit-testable, but "is it reachable, does it return 200, is the JSON shaped
the way clients expect" are three facts that live in the wiring. It is also the endpoint a load balancer
will call every few seconds forever, which makes it the one most worth testing and the one most likely
to be written without a test.

Note the property-name mapping you did not configure: the server writes `status` and `orders` (ASP.NET
Core's camelCase policy) and `ReadFromJsonAsync` reads them into `Status`/`Orders` because
`System.Net.Http.Json` defaults to case-insensitive web options. Two defaults happening to agree is
exactly what an integration test verifies and a unit test cannot see.

### 2. PUT, and three status codes that only HTTP can check

```csharp
// OrderStore.cs
public Order? Replace(int id, IReadOnlyList<OrderLine> lines)
{
    var (subtotal, tax, total) = Totals.For(lines);      // slow-ish work OUTSIDE the lock
    lock (_lock)
    {
        var index = _orders.FindIndex(o => o.Id == id);
        if (index < 0) return null;
        var updated = new Order(id, lines, subtotal, tax, total);   // the id is not the caller's to change
        _orders[index] = updated;
        return updated;
    }
}

// Api.cs
app.MapPut("/orders/{id:int}", (int id, NewOrder? dto, OrderStore store) =>
{
    // Guard order is a decision, not an accident: a request we cannot parse is
    // bad regardless of whether the resource exists.
    var errors = OrderRules.Validate(dto);
    if (errors.Count > 0) return Results.BadRequest(new { errors });

    return store.Replace(id, OrderRules.ToLines(dto!)) is { } order
        ? Results.Ok(order)
        : Results.NotFound(new { error = $"no order with id {id}" });
});
```

WHY: look at what this endpoint actually *does* — one validation call, one store call, then it picks
between three status codes. That is the entire risk surface, and all of it is invisible to a unit test:
`Results.Ok`, `Results.NotFound`, and `Results.BadRequest` are all valid C# that compiles and runs
whichever one you pick. Same shape as the original's bug, which is why PUT is worth adding here rather
than another calculation.

The 400-before-404 ordering is worth defending because both orders ship in real APIs. Validating first
gives a malformed request one consistent answer whether or not the id exists — simpler to document, and
it declines to leak which ids exist to someone who has not sent a well-formed request. The opposite order
is defensible when existence is public anyway. What is *not* defensible is having no opinion, because
then the answer depends on which check the last person happened to write first. (Re-stamping the id
inside `Replace` is cs#21's `Mutate` instinct: PUT replaces *contents*, not identity.)

### 3. A discount, and the invariant that must survive it

```csharp
// Order.cs
public record Order(int Id, IReadOnlyList<OrderLine> Lines,
                    decimal Subtotal, decimal Discount, decimal Tax, decimal Total);

public static class Totals
{
    public const decimal TaxRate = 0.08m;
    public const decimal DiscountThreshold = 100m;
    public const decimal DiscountRate = 0.10m;

    /// INVARIANT: Subtotal - Discount + Tax == Total, exactly, for all inputs.
    public static (decimal Subtotal, decimal Discount, decimal Tax, decimal Total) For(IReadOnlyList<OrderLine> lines)
    {
        var subtotal = lines.Sum(line => Money.Round(line.Qty * line.UnitPrice));
        var discount = subtotal >= DiscountThreshold ? Money.Round(subtotal * DiscountRate) : 0m;
        var tax = Money.Round((subtotal - discount) * TaxRate);
        var total = subtotal - discount + tax;      // three rounded numbers: exact by construction
        return (subtotal, discount, tax, total);
    }
}

// Tests.cs — the property loop, updated
for (int qty = 1; qty <= 30; qty++)
    for (int step = 1; step <= 40; step++)
    {
        var (subtotal, discount, tax, total) = Totals.For([new OrderLine("X", qty, step * 0.255m)]);
        checkedCombinations++;
        if (subtotal - discount + tax != total) violations++;
        if (Money.Round(discount) != discount || Money.Round(tax) != tax) violations++;
    }
```

WHY: the shape of the invariant changed, and that is the lesson. `Subtotal + Tax == Total` was never the
real rule — the real rule is "the numbers the customer can see add up the way the customer will add
them", and adding a discount line changes what that sentence means. A property test you must *edit* when
the business rule changes is doing its job; one that keeps passing unchanged was probably asserting the
wrong thing.

Charging tax on the discounted amount rather than the subtotal is a genuine business decision (in some
jurisdictions a legal one) hiding inside one pair of parentheses. And the boundary: `>=` versus `>` is
one character, worth ten pence on every order landing exactly on 100.00, and completely invisible
without a test that uses exactly 100.00. Every threshold deserves three tests — below, on, above.

### 4. One server per scenario

```csharp
// HttpTests.cs
public static void Run() => RunAsync().GetAwaiter().GetResult();

private static async Task RunAsync()
{
    await WithServer(CreateAndFetchScenario);
    await WithServer(ValidationScenario);
    await WithServer(DeleteScenario);
}

/// Starts a fresh app on a fresh random port, runs ONE scenario against it,
/// and shuts it down — so no scenario can see another's data.
private static async Task WithServer(Func<HttpClient, Task> scenario)
{
    var app = Api.Build([], quiet: true);
    app.Urls.Clear();
    app.Urls.Add("http://127.0.0.1:0");

    await app.StartAsync();
    try
    {
        using var http = new HttpClient
        {
            BaseAddress = new Uri(app.Urls.First()),
            Timeout = TimeSpan.FromSeconds(15),
        };
        await scenario(http);
    }
    finally
    {
        await app.StopAsync();
        await app.DisposeAsync();
    }
}
```

WHY: shared state between tests is the number one cause of suites that pass individually and fail
together, or pass in one order and fail in another — and the failure message never mentions the real
cause, because the real cause is a test that ran earlier. Every scenario starting from an empty world
means a red test tells you about the code, not about its neighbours.

The cost is real and worth naming: each `WithServer` pays app startup, roughly a tenth of a second.
Thirty scenarios is three seconds — fine. Three hundred is thirty, at which point you either share one
server and reset state between scenarios, or move to `WebApplicationFactory`, whose in-memory transport
removes the socket entirely. Note where the leverage is: `OrderStore` is registered *per app*, so "fresh
app" and "fresh data" are the same act. With a static, or a real database, isolation would need its own
design — which is why in-memory-by-default is worth keeping as long as you can.

### 5. Swap a service, the way `WebApplicationFactory` does

```csharp
// Api.cs
public static WebApplication Build(string[] args, bool quiet = false,
                                   Action<IServiceCollection>? configureServices = null)
{
    var builder = WebApplication.CreateBuilder(args);
    if (quiet) builder.Logging.ClearProviders();

    builder.Services.AddSingleton<OrderStore>();

    // LAST, so a test's registration overrides the app's. This one line is
    // what WebApplicationFactory's WithWebHostBuilder(...ConfigureServices...)
    // gives you, and it is the whole reason that package exists.
    configureServices?.Invoke(builder.Services);

    var app = builder.Build();
    MapEndpoints(app);
    return app;
}

// OrderStore.cs — the members a double needs to replace become virtual
public virtual IReadOnlyList<Order> All() { lock (_lock) return _orders.ToList(); }
public virtual Order? Find(int id) { lock (_lock) return _orders.FirstOrDefault(o => o.Id == id); }
public virtual Order Add(IReadOnlyList<OrderLine> lines) { /* ...unchanged... */ }
public virtual bool Delete(int id) { lock (_lock) return _orders.RemoveAll(o => o.Id == id) > 0; }

// HttpTests.cs — the fault-injecting double
private class FailingOrderStore : OrderStore
{
    public override IReadOnlyList<Order> All() => throw new InvalidOperationException("the database is down");
}

// ...and the overload that takes it
private static async Task WithServer(Func<HttpClient, Task> scenario, Action<IServiceCollection>? configure = null)
{
    var app = Api.Build([], quiet: true, configure);
    // ...as before...
}
```

WHY: this is the move that makes integration testing *practical* rather than merely possible. Without
it, every integration test must reach the state it needs through the API itself — three POSTs before the
assertion you care about — which is slow and, worse, couples every test to endpoints it is not testing.
Break POST and forty unrelated tests go red. Seeding the store directly means a test about *reading*
depends only on reading.

The failure case is the part you cannot get any other way. "What does this API do when the database is
down?" has no valid request that provokes it. Injecting a store that throws answers it in milliseconds,
about the *real* pipeline: routing, the exception reaching Kestrel, and a 500 with no stack trace
attached because the app is not in Development. (Set `ASPNETCORE_ENVIRONMENT=Development` and run it
again — the body changes completely, which is worth knowing before a customer finds it.)

Ordering is the one thing to get right: `configureServices` runs after the app's own registrations
because resolving a single service returns the **last** registration for that type. Run it first and the
app overwrites your double, the test passes against the real store, and you believe something false —
the worst outcome available to a test.

// THE COMPOSITION ROOT, extracted into a function.
//
// This one refactor is what makes integration testing possible at all. In
// every other project in this track, Program.cs both *builds* the app and
// *runs* it, in the same breath — so there is no way for a test to get hold of
// a configured app without also starting a server on the real port.
//
// Splitting "build" from "run" gives two callers the same app:
//
//   Program.cs   builds it, then runs it on http://localhost:5035
//   HttpTests.cs builds it, then runs it on port 0 (a random free port), makes
//                real HTTP requests against it, and stops it again
//
// The tests exercise the app the app, not a copy of it — same endpoints, same
// DI registrations, same JSON serialization, same middleware. If this function
// changes, both callers change with it, which is the property that makes the
// test suite trustworthy a year from now.

public static class Api
{
    public static WebApplication Build(string[] args, bool quiet = false)
    {
        var builder = WebApplication.CreateBuilder(args);

        // Tests silence the logger so the Check output stays readable. The real
        // run keeps it, because "Now listening on..." is useful information.
        if (quiet) builder.Logging.ClearProviders();

        builder.Services.AddSingleton<OrderStore>();

        var app = builder.Build();
        MapEndpoints(app);
        return app;
    }

    // Every endpoint here is pure translation: parse, delegate, pick a status
    // code. There is no arithmetic and no business rule — those live in
    // Totals and OrderRules, where unit tests can reach them without HTTP.
    // What is LEFT here is exactly what only an integration test can check.
    private static void MapEndpoints(WebApplication app)
    {
        app.MapGet("/orders", (OrderStore store) => Results.Ok(store.All()));

        // `{id:int}` is a route CONSTRAINT: /orders/abc does not match this
        // route at all, so it is a 404 (that URL names no resource) rather
        // than a 400. Without the constraint it would be a binding failure —
        // also fine, also a deliberate choice. The point is that it IS a
        // choice, and a test should pin whichever one you made.
        app.MapGet("/orders/{id:int}", (int id, OrderStore store) =>
            store.Find(id) is { } order
                ? Results.Ok(order)
                : Results.NotFound(new { error = $"no order with id {id}" }));   // the original's 200-with-null

        app.MapPost("/orders", (NewOrder? dto, OrderStore store) =>
        {
            var errors = OrderRules.Validate(dto);
            if (errors.Count > 0) return Results.BadRequest(new { errors });

            var order = store.Add(OrderRules.ToLines(dto!));

            // 201 + Location: the status says "I made something", the header
            // says where it lives (cs#16). A client no longer has to build the
            // URL from an id and hope it guessed the route right.
            return Results.Created($"/orders/{order.Id}", order);
        });

        app.MapDelete("/orders/{id:int}", (int id, OrderStore store) =>
            store.Delete(id)
                ? Results.NoContent()
                : Results.NotFound(new { error = $"no order with id {id}" }));
    }
}

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

using System.Text;

// THE INTEGRATION SUITE — a real HTTP server, in this process, on a random
// free port, for the duration of these assertions.
//
// The harness is four moves:
//
//   1. Api.Build([], quiet: true)      the same app Program.cs runs
//   2. app.Urls.Add("http://127.0.0.1:0")
//                                      port 0 means "OS, pick a free one".
//                                      Hard-coding 5035 would make the test
//                                      fail whenever you left the real server
//                                      running — a flaky test nobody trusts.
//   3. await app.StartAsync()          Kestrel binds, then REWRITES app.Urls
//                                      with the port it actually got. That is
//                                      how we learn where to send requests.
//   4. await app.StopAsync()           in a `finally`, always. A test that
//                                      leaks a listening socket poisons every
//                                      test after it.
//
// Real projects use `WebApplicationFactory<T>` from
// Microsoft.AspNetCore.Mvc.Testing (a NuGet package) instead of these four
// lines. It does the same job with extras — an in-memory transport so no real
// socket is opened, and hooks to swap services for fakes. We hand-roll it here
// for the same reason this repo hand-rolls `Check` instead of using xUnit:
// offline, zero setup, and you get to see the mechanism before the convenience.

public static class HttpTests
{
    // Tests.Run() is synchronous, so this is the one place the async world is
    // bridged back. GetAwaiter().GetResult() rather than .Result so exceptions
    // arrive unwrapped instead of inside an AggregateException.
    public static void Run() => RunAsync().GetAwaiter().GetResult();

    private static async Task RunAsync()
    {
        var app = Api.Build([], quiet: true);
        app.Urls.Clear();
        app.Urls.Add("http://127.0.0.1:0");

        await app.StartAsync();
        try
        {
            var baseAddress = app.Urls.First();
            Check.True(baseAddress.StartsWith("http://127.0.0.1:") && !baseAddress.EndsWith(":0"),
                $"[http] Kestrel bound a real port and told us which one ({baseAddress})");

            using var http = new HttpClient
            {
                BaseAddress = new Uri(baseAddress),
                Timeout = TimeSpan.FromSeconds(15),   // a hung request must fail, not hang the suite
            };

            await Suite(http);
        }
        finally
        {
            // Cleanly, and even if an assertion threw.
            await app.StopAsync();
            await app.DisposeAsync();
        }
    }

    private static async Task Suite(HttpClient http)
    {
        // ---- the empty world -------------------------------------------------
        var empty = await http.GetAsync("/orders");
        Check.Equal(200, (int)empty.StatusCode, "[http] GET /orders on a fresh server is 200");
        Check.Equal("application/json", empty.Content.Headers.ContentType?.MediaType,
            "[http] ...and says it is JSON");
        Check.Equal(0, (await empty.Content.ReadFromJsonAsync<List<OrderDto>>())!.Count,
            "[http] ...with an empty array, not null");

        // ---- creating: the status code and the header ------------------------
        var created = await http.PostAsJsonAsync("/orders", new
        {
            lines = new[] { new { sku = "BOOK-1", qty = 3, unitPrice = 19.99m } },
        });
        Check.Equal(201, (int)created.StatusCode,
            "[http] POST answers 201 Created, not 200 OK (the original's bug #3)");
        Check.Equal("/orders/1", created.Headers.Location?.ToString(),
            "[http] ...and a Location header saying where the order lives");

        var body = await created.Content.ReadFromJsonAsync<OrderDto>();
        Check.Equal(1, body!.Id, "[http] the new order has id 1");
        Check.Equal(59.97m, body.Subtotal, "[http] 3 x 19.99 = 59.97 (the original said 59.97000000000000063...)");
        Check.Equal(4.80m, body.Tax, "[http] 8% of 59.97, rounded to cents");
        Check.Equal(64.77m, body.Total, "[http] and a total an accountant would recognise");
        Check.Equal(body.Total, body.Subtotal + body.Tax,
            "[http] THE INVARIANT, checked on the JSON the client actually receives");

        // ---- the Location header is a promise; test that it resolves ---------
        var followed = await http.GetAsync(created.Headers.Location!.ToString());
        Check.Equal(200, (int)followed.StatusCode, "[http] following Location works");
        Check.Equal(64.77m, (await followed.Content.ReadFromJsonAsync<OrderDto>())!.Total,
            "[http] ...and lands on the order we just created");

        var listed = await (await http.GetAsync("/orders")).Content.ReadFromJsonAsync<List<OrderDto>>();
        Check.Equal(1, listed!.Count, "[http] the collection now has one order");
        Check.Equal(64.77m, listed[0].Total, "[http] ...with the same total as the create response");

        // ---- the missing order: the bug this project is named after ----------
        var missing = await http.GetAsync("/orders/999");
        Check.Equal(404, (int)missing.StatusCode,
            "[http] a missing order is 404 — NOT 200 with a null body (the original's bug #2)");
        var missingError = await missing.Content.ReadFromJsonAsync<ErrorDto>();
        Check.True(missingError!.Error.Contains("999"), "[http] ...and the body names the id");

        var badId = await http.GetAsync("/orders/abc");
        Check.Equal(404, (int)badId.StatusCode,
            "[http] a non-integer id matches no route at all, so: 404");

        // ---- validation: 400s, with every problem listed ---------------------
        var noLines = await http.PostAsJsonAsync("/orders", new { lines = Array.Empty<object>() });
        Check.Equal(400, (int)noLines.StatusCode, "[http] an order with no lines is 400");
        Check.Equal(1, (await noLines.Content.ReadFromJsonAsync<ErrorsDto>())!.Errors.Length,
            "[http] ...with exactly one clear message");

        var badLine = await http.PostAsJsonAsync("/orders", new
        {
            lines = new[] { new { sku = "", qty = 0, unitPrice = -1m } },
        });
        Check.Equal(400, (int)badLine.StatusCode, "[http] a junk line is 400");
        Check.Equal(3, (await badLine.Content.ReadFromJsonAsync<ErrorsDto>())!.Errors.Length,
            "[http] ...listing ALL three problems, so the client fixes them in one round trip");

        var malformed = await http.PostAsync("/orders",
            new StringContent("{ this is not json", Encoding.UTF8, "application/json"));
        Check.Equal(400, (int)malformed.StatusCode,
            "[http] malformed JSON is 400 — the framework handles it, and this proves it");

        var listStillOne = await (await http.GetAsync("/orders")).Content.ReadFromJsonAsync<List<OrderDto>>();
        Check.Equal(1, listStillOne!.Count, "[http] and none of those failures created anything");

        // ---- deleting --------------------------------------------------------
        var deleted = await http.DeleteAsync("/orders/1");
        Check.Equal(204, (int)deleted.StatusCode, "[http] DELETE answers 204 No Content");
        Check.Equal(0L, deleted.Content.Headers.ContentLength.GetValueOrDefault(),
            "[http] ...with an empty body, as 204 requires");
        Check.Equal(404, (int)(await http.GetAsync("/orders/1")).StatusCode,
            "[http] the deleted order is really gone");
        Check.Equal(404, (int)(await http.DeleteAsync("/orders/1")).StatusCode,
            "[http] deleting it again is 404, not a cheerful 204");

        // ---- ids are not recycled -------------------------------------------
        var awkward = await http.PostAsJsonAsync("/orders", new
        {
            lines = new[] { new { sku = "TILE-1", qty = 3, unitPrice = 0.335m } },
        });
        var awk = await awkward.Content.ReadFromJsonAsync<OrderDto>();
        Check.Equal(2, awk!.Id, "[http] the next order is id 2 — deleting 1 does not free the id");
        Check.Equal(1.01m, awk.Subtotal,
            "[http] 3 x 0.335 = 1.005, rounded AWAY FROM ZERO to 1.01 (banker's rounding would say 1.00)");
        Check.Equal(0.08m, awk.Tax, "[http] tax on 1.01");
        Check.Equal(1.09m, awk.Total, "[http] and the total");
        Check.Equal(awk.Total, awk.Subtotal + awk.Tax,
            "[http] the invariant survives an awkward price and a JSON round trip");
    }

    // Small read-only shapes for the assertions. They deliberately don't
    // mention `Lines`: System.Text.Json ignores JSON properties a target type
    // doesn't have, so a test can name only what it cares about.
    private record OrderDto(int Id, decimal Subtotal, decimal Tax, decimal Total);
    private record ErrorDto(string Error);
    private record ErrorsDto(string[] Errors);
}

// Money, in two rules that fit on a postcard:
//
//   1. NEVER `double`. Doubles are binary fractions, so 19.99 is stored as
//      19.989999999999998436805981327 — close enough to display, not close
//      enough to add up a thousand times. `decimal` stores base-10 fractions
//      exactly, which is why .NET has it and why every currency amount in this
//      project is one. (The other correct answer is an integer count of cents.)
//
//   2. Round AWAY FROM ZERO at midpoints. `Math.Round(2.665m, 2)` gives 2.66,
//      because .NET defaults to BANKER'S ROUNDING — ties go to the nearest
//      even digit, which is unbiased over many samples and is *not* what a
//      receipt does. Invoices round .5 up. Always.
//
// Both defaults are traps precisely because they are invisible: the code looks
// right, the numbers look right, and the error is in the last cent of the
// thousandth invoice.

public static class Money
{
    /// Round to whole cents the way an invoice does.
    public static decimal Round(decimal amount) => Math.Round(amount, 2, MidpointRounding.AwayFromZero);
}

// The domain. Records, `decimal`, and one pure function that owns every
// arithmetic decision in the application.

public record OrderLine(string Sku, int Qty, decimal UnitPrice);

public record Order(
    int Id,
    IReadOnlyList<OrderLine> Lines,
    decimal Subtotal,
    decimal Tax,
    decimal Total);

// The shapes HTTP sends us, kept separate from the domain (cs#17). Everything
// here is nullable or unvalidated on purpose: this is what a stranger typed.
public record NewOrderLine(string? Sku, int Qty, decimal UnitPrice);
public record NewOrder(List<NewOrderLine>? Lines);

public static class Totals
{
    public const decimal TaxRate = 0.08m;

    /// THE INVARIANT THIS FUNCTION EXISTS TO GUARANTEE:
    ///
    ///     Subtotal + Tax == Total,   exactly, for every possible input.
    ///
    /// The original could not promise that, because it rounded the total and
    /// left the pieces unrounded — so the response showed three numbers that
    /// did not add up, and every screen that re-derived one of them from the
    /// others disagreed with every screen that didn't.
    ///
    /// The order of operations is the whole trick: round each LINE, sum the
    /// rounded lines, round the tax, and then add two already-rounded numbers.
    /// Adding rounded values can never need rounding again, so the total is
    /// exact by construction rather than by luck.
    ///
    /// Rounding per line (rather than only at the end) matters for a duller
    /// reason: the invoice PRINTS line totals, and the printed lines must add
    /// up to the printed subtotal. A customer with a calculator is a test suite.
    public static (decimal Subtotal, decimal Tax, decimal Total) For(IReadOnlyList<OrderLine> lines)
    {
        var subtotal = lines.Sum(line => Money.Round(line.Qty * line.UnitPrice));
        var tax = Money.Round(subtotal * TaxRate);
        var total = subtotal + tax;
        return (subtotal, tax, total);
    }
}

public static class OrderRules
{
    public const int MaxLines = 100;

    /// Every problem at once, named by line number, with no HTTP anywhere in
    /// sight — so the tests for it never start a server (cs#17, cs#22).
    public static IReadOnlyList<string> Validate(NewOrder? dto)
    {
        var errors = new List<string>();

        if (dto?.Lines is null || dto.Lines.Count == 0)
        {
            errors.Add("an order needs at least one line");
            return errors;                        // every other rule would be noise
        }

        if (dto.Lines.Count > MaxLines)
            errors.Add($"an order may have at most {MaxLines} lines");

        for (int i = 0; i < dto.Lines.Count; i++)
        {
            var line = dto.Lines[i];
            if (string.IsNullOrWhiteSpace(line.Sku)) errors.Add($"line {i + 1}: sku is required");
            if (line.Qty <= 0) errors.Add($"line {i + 1}: qty must be greater than 0");
            if (line.UnitPrice < 0) errors.Add($"line {i + 1}: unitPrice must not be negative");
        }

        return errors;
    }

    /// Only ever called with a `dto` that Validate approved, which is why the
    /// `!` here is honest rather than hopeful (cs#05).
    public static IReadOnlyList<OrderLine> ToLines(NewOrder dto)
        => dto.Lines!.Select(l => new OrderLine(l.Sku!.Trim(), l.Qty, l.UnitPrice)).ToList();
}

// Storage, behind a lock (cs#21). Note that `Add` is where totals are
// computed: an Order cannot exist in this store without correct totals,
// because there is no other way to make one.

public class OrderStore
{
    private readonly List<Order> _orders = new();
    private readonly object _lock = new();
    private int _nextId = 1;

    public IReadOnlyList<Order> All()
    {
        lock (_lock) return _orders.ToList();
    }

    public Order? Find(int id)
    {
        lock (_lock) return _orders.FirstOrDefault(o => o.Id == id);
    }

    public Order Add(IReadOnlyList<OrderLine> lines)
    {
        var (subtotal, tax, total) = Totals.For(lines);
        lock (_lock)
        {
            var order = new Order(_nextId++, lines, subtotal, tax, total);
            _orders.Add(order);
            return order;
        }
    }

    public bool Delete(int id)
    {
        lock (_lock) return _orders.RemoveAll(o => o.Id == id) > 0;
    }
}

